//! Raw, unsafe FFI bindings to LiteRT LM's C API 1.0.0 (every public header:
//! `engine.h`, `conversation.h`, `embedding_engine.h`, `model_info.h`,
//! `experimental.h`, `error_reporter.h`), generated by `bindgen` at build
//! time. See the `litertlm-rs` crate for a safe wrapper.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
